var PLUGIN_LANGUAGE_IDS = LANGUAGES.map((item) => item.id);
var EXTRA_LANGUAGE_IDS = Object.keys(SHARE_VIEWER_UI_EXTRA);
var isPluginLanguage = (value) => PLUGIN_LANGUAGE_IDS.includes(value);
var isExtraLanguage = (value) => EXTRA_LANGUAGE_IDS.includes(value);
function nativeNameOf(language2) {
  const known = [...LANGUAGES, ...OUTPUT_LANGUAGES].find((item) => item.id === language2);
  if (known) return known.label;
  try {
    const display = new Intl.DisplayNames([language2], { type: "language" }).of(language2);
    return display != null ? display : language2;
  } catch (e) {
    return language2;
  }
}
function shareViewerUiExtras(languages) {
  const uiByLanguage = {};
  const languageNames = {};
  for (const language2 of languages) {
    uiByLanguage[language2] = isPluginLanguage(language2) ? shareViewerUiFor(language2) : isExtraLanguage(language2) ? { ...SHARE_VIEWER_UI_EXTRA[language2] } : { ...shareViewerUiFor("en"), lang: language2 };
    languageNames[language2] = nativeNameOf(language2);
  }
  return { uiByLanguage, languageNames };
}

